import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const mockSimilarTracks = [
  { id: 1, name: 'Similar Track 1', bpm: 122, genre: 'House' },
  { id: 2, name: 'Similar Track 2', bpm: 121, genre: 'Techno' },
  { id: 3, name: 'Similar Track 3', bpm: 119, genre: 'Trance' },
  // Add more mock similar tracks
];

const SimilarTracks = () => {
  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const track = params.get('track');
  const [similarTracks, setSimilarTracks] = useState([]);

  useEffect(() => {
    // Mock fetching similar tracks
    // This will be replaced with a real API call later
    setSimilarTracks(mockSimilarTracks);
  }, [track]);

  return (
    <div>
      <h2>Similar Tracks for: {track}</h2>
      <ul>
        {similarTracks.map((similarTrack) => (
          <li key={similarTrack.id}>
            {similarTrack.name} - {similarTrack.genre} ({similarTrack.bpm} BPM)
          </li>
        ))}
      </ul>
    </div>
  );
};

export default SimilarTracks;
